  "currentTexts": {
    "keyName": {
      "sourceKey": "Spell_GnarPassive_Name",
      "text": "狂怒基因"
    },
    "keySummary": {
      "sourceKey": "Spell_GnarPassive_Summary",
      "text": "在战斗时，纳尔会产生怒气。在怒气到达最大值时，他的下一个技能将使他变形成巨型纳尔，获得强化的生存能力并能使用新的技能。"
    },
    "keyTooltip": {
      "sourceKey": "Spell_GnarPassive_Tooltip",
      "text": "纳尔可通过造成和受到伤害来生成<keywordMajor>怒气</keywordMajor>。在满层<keywordMajor>怒气</keywordMajor>时，他的下一个技能会使他变形为<keywordMajor>巨型纳尔</keywordMajor>，持续15秒。<br><br><keywordMajor>小型纳尔：</keywordMajor>获得<speed>@TotalMS@移动速度</speed>，<attackSpeed>@TotalAS@攻击速度</attackSpeed>，以及@TotalAttackRange@攻击距离。<br><br><keywordMajor>巨型纳尔：</keywordMajor>获得<healing>@TotalMegaGnarHealth@最大生命值</healing>，<scaleArmor>@TotalMegaGnarArmor@护甲</scaleArmor>，<scaleMR>@TotalMegaGnarMR@魔法抗性</scaleMR>，和<physicalDamage>@TotalMegaGnarAD@攻击力</physicalDamage>。"
    },
    "keyTooltipExtended": {
      "sourceKey": "Spell_GnarPassive_TooltipExtended",
      "text": "{{spell_GnarPassive_Tooltip}}<br><br><rules>在满层<keywordMajor>怒气</keywordMajor>时，如果纳尔不使用任一技能，那么他会在4秒后自动变身。<br>如果纳尔在13秒内未造成或受到任何伤害，那么<keywordMajor>怒气</keywordMajor>就会开始衰减。<br>在对英雄造成伤害时，会生成更多<keywordMajor>怒气</keywordMajor>。</rules>"
    }
  },
