  "currentTexts": {
    "keyName": {
      "sourceKey": "Spell_KledQ_Name",
      "text": "飞索捕熊器"
    },
    "keySummary": {
      "sourceKey": "Spell_KledQ_Summary",
      "text": "克烈投掷一个捕熊器，钩住一个敌人并造成伤害。如果短时间内牵引没有被打破，那么目标会受到额外物理伤害并被拽向克烈。<br><br>当处于非骑乘状态下时，这个技能会被替换为【随身手枪】——一个远程枪击技能，可将克烈击退并回复勇气值。"
    },
    "keyTooltip": {
      "sourceKey": "Spell_KledQ_Tooltip",
      "text": "<keywordMajor>骑乘状态：</keywordMajor>克烈扔出一个捕熊器来钩住第一个命中的敌方英雄或大型野怪并造成<physicalDamage>@TotalDamage@物理伤害</physicalDamage>。<br><br>如果克烈在一名被钩住的敌人附近呆@TetherPopTime@秒，那么他就会将该敌人拽向他，并造成<physicalDamage>@TotalYankDamage@物理伤害</physicalDamage>，<status>拉拽</status>该敌人，造成持续@SlowDuration@秒的@SlowAmount*-100@%<status>减速</status>。"
    },
    "keyCost": {
      "sourceKey": "Spell_Cost_NoCost",
      "text": "无消耗"
    },
    "keyTooltipExtendedBelowLine": {
      "sourceKey": "Spell_KledQ_TooltipExtendedBelowLine",
      "text": "<rules>在钩住目标时，克烈拥有该敌人的<keywordStealth>真实视野</keywordStealth>。<br>对小兵造成@MinionDamageMultiplier*100@%伤害。</rules>"
    },
    "keyTooltipExtended": {
      "sourceKey": "Spell_KledQ_TooltipExtended",
      "text": "{{spell_KledQ_Tooltip}}<br><br><keywordMajor>非骑乘状态：</keywordMajor>克烈发射一发霰弹枪，造成<physicalDamage>@DismountedQDamage@物理伤害</physicalDamage>并使克烈因后坐力而向后位移。第一颗之后的弹丸造成较少伤害。<br><br>每颗弹丸在命中一名敌方英雄或史诗级野怪时都会回复<keywordMajor>勇气</keywordMajor>。"
    }
  },
